'use strict';
const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function read(k,d){try{return JSON.parse(localStorage.getItem('forma-'+k))??d}catch{return d}}
function save(k,v){try{localStorage.setItem('forma-'+k,JSON.stringify(v));return true}catch{toast('Хранилище заполнено. Экспортируйте данные и освободите место.');return false}}
let settings=read('settings',{dark:false,wall:0,name:'',focus:false}),notes=read('notes',[{id:'welcome',title:'Место для новых идей',text:'Добро пожаловать в Forma.\n\nЭто ваше пространство для мыслей, планов и маленьких открытий.\n\n• Создавайте заметки и файлы\n• Собирайте планы в календаре\n• Включайте фокус на 25 минут\n\nВсё сохраняется в этом браузере. Для резервной копии используйте экспорт в Настройках.'}]),files=read('files',[{id:'readme',name:'Начните здесь.txt',type:'text/plain',text:'Добро пожаловать в Forma OS!\n\nДвойной клик открывает файл. Импортируйте свои документы или создайте текстовый файл.\n\n⌘ / Ctrl + K — поиск приложений\nEsc — закрыть меню\n\nДанные хранятся локально в этом браузере. Экспортируйте резервную копию в Настройках.\nТерминал работает с виртуальной файловой системой, а не с вашей ОС.',folder:'Документы'}]),events=read('events',{}),selectedNote=notes[0]?.id,z=20,focused=null;
const apps={files:{name:'Файлы',icon:'◧'},browser:{name:'Браузер',icon:'◈'},notes:{name:'Заметки',icon:'≡'},calendar:{name:'Календарь',icon:String(new Date().getDate())},music:{name:'Музыка',icon:'♫'},calculator:{name:'Калькулятор',icon:'⊞'},terminal:{name:'Терминал',icon:'›_'},settings:{name:'Настройки',icon:'⚙'},trash:{name:'Корзина',icon:'♲'}};
let wins={},folder='Все файлы';
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(toast.t);toast.t=setTimeout(()=>$('#toast').classList.remove('show'),3000)}
function applySettings(){document.body.classList.toggle('dark',settings.dark);document.body.classList.toggle('focus-mode',settings.focus);const walls=['radial-gradient(ellipse at 55% 25%,#eeeee9,#cececa 50%,#aaaca7)','radial-gradient(ellipse at 55% 25%,#e9eedd,#b8c5a4 50%,#7b8d70)','radial-gradient(ellipse at 55% 25%,#eee6dd,#d3b8ad 50%,#a98e89)'];$('#wallpaper').style.background=walls[settings.wall]||walls[0];$('#greeting').textContent=settings.name?`Ваше пространство, ${settings.name}.`:'Всё на своём месте.';save('settings',settings)}
applySettings();
$('#dock').innerHTML=Object.entries(apps).map(([id,a])=>`<button class="dock-item" data-app="${id}" aria-label="${a.name}"><span class="app-icon">${a.icon}</span></button>`).join('');
$$('[data-app]').forEach(b=>b.onclick=()=>openApp(b.dataset.app));$$('[data-open]').forEach(b=>b.ondblclick=()=>openApp(b.dataset.open));$$('[data-open]').forEach(b=>b.onclick=()=>openApp(b.dataset.open));
function clock(){const d=new Date();$('#clock').textContent=d.toLocaleDateString('ru-RU',{weekday:'short',day:'numeric',month:'short'})+' '+d.toLocaleTimeString('ru-RU',{hour:'2-digit',minute:'2-digit'});$('#day-number').textContent=d.getDate();$('#day-description').textContent=d.toLocaleDateString('ru-RU',{month:'long',weekday:'long'});$('#week').innerHTML=['П','В','С','Ч','П','С','В'].map((x,i)=>`<span class="${i===(d.getDay()+6)%7?'today':''}">${x}</span>`).join('')}
clock();setInterval(clock,1000);$('#quick-note').value=read('quick','');$('#quick-note').oninput=e=>save('quick',e.target.value);
function stats(){$('#file-count').textContent=files.filter(f=>!f.deleted).length}stats();
let remaining=1500,end=0,timerId=null;
function updateTimer(){if(end)remaining=Math.max(0,Math.ceil((end-Date.now())/1000));$('#timer').textContent=String(Math.floor(remaining/60)).padStart(2,'0')+':'+String(remaining%60).padStart(2,'0');if(!remaining&&end){clearInterval(timerId);timerId=null;end=0;$('#timer-toggle').textContent='↻';toast('Сессия завершена. Пора сделать небольшой перерыв.')}}
$('#timer-toggle').onclick=()=>{if(timerId){updateTimer();clearInterval(timerId);timerId=null;end=0;$('#timer-toggle').textContent='▶'}else{if(!remaining)remaining=1500;end=Date.now()+remaining*1000;timerId=setInterval(updateTimer,250);$('#timer-toggle').textContent='Ⅱ'}updateTimer()};
function focusWin(id){focused=id;const w=wins[id];if(!w)return;w.hidden=false;w.style.display='flex';w.style.zIndex=++z;$('#active-app').textContent=apps[id]?.name||w.dataset.title}
function openApp(id){closeOverlay();if(wins[id]){focusWin(id);return}const a=apps[id];if(!a)return;const w=document.createElement('section');w.className='window';w.dataset.title=a.name;w.setAttribute('aria-label',a.name);w.style.left=(Math.min(innerWidth-750,300)+Object.keys(wins).length*22)+'px';w.style.top=(95+Object.keys(wins).length*22)+'px';w.innerHTML=`<div class="titlebar"><span class="window-app-mark" aria-hidden="true">${a.icon}</span><div class="window-title">${a.name}</div><div class="window-controls"><button data-window-action="minimize" title="Свернуть" aria-label="Свернуть"><svg viewBox="0 0 16 16" aria-hidden="true"><path d="M3 8.5h10"/></svg></button><button data-window-action="maximize" title="Развернуть" aria-label="Развернуть" aria-pressed="false"><svg viewBox="0 0 16 16" aria-hidden="true"><rect x="3.5" y="3.5" width="9" height="9" rx="1"/></svg></button><button data-window-action="close" title="Закрыть" aria-label="Закрыть"><svg viewBox="0 0 16 16" aria-hidden="true"><path d="m4 4 8 8m0-8-8 8"/></svg></button></div></div><div class="window-body"></div>`;$('#windows').append(w);wins[id]=w;const controls={minimize:$('[data-window-action="minimize"]',w),maximize:$('[data-window-action="maximize"]',w),close:$('[data-window-action="close"]',w)};controls.close.onclick=()=>{if(id==='music'){const audio=$('audio',w);if(audio){audio.pause();if(audio.src)URL.revokeObjectURL(audio.src)}}w.remove();delete wins[id];$(`[data-app="${id}"]`).classList.remove('running');$('#active-app').textContent='Forma'};controls.minimize.onclick=()=>{w.style.display='none';$('#active-app').textContent='Forma'};const toggleMaximize=()=>{const maximized=w.classList.toggle('maximized');const label=maximized?'Восстановить размер':'Развернуть';controls.maximize.title=label;controls.maximize.setAttribute('aria-label',label);controls.maximize.setAttribute('aria-pressed',String(maximized));controls.maximize.innerHTML=maximized?'<svg viewBox="0 0 16 16" aria-hidden="true"><path d="M6 5V3.5h6.5V10H11"/><rect x="3.5" y="6" width="6.5" height="6.5" rx=".5"/></svg>':'<svg viewBox="0 0 16 16" aria-hidden="true"><rect x="3.5" y="3.5" width="9" height="9" rx="1"/></svg>'};controls.maximize.onclick=toggleMaximize;$('.titlebar',w).ondblclick=e=>{if(!e.target.closest('button'))toggleMaximize()};w.onpointerdown=()=>focusWin(id);const bar=$('.titlebar',w);bar.onpointerdown=e=>{if(e.target.closest('button')||w.classList.contains('maximized'))return;let x=e.clientX,y=e.clientY,l=w.offsetLeft,t=w.offsetTop;bar.setPointerCapture(e.pointerId);bar.onpointermove=ev=>{w.style.left=Math.max(0,Math.min(innerWidth-100,l+ev.clientX-x))+'px';w.style.top=Math.max(36,Math.min(innerHeight-145,t+ev.clientY-y))+'px'};bar.onpointerup=()=>bar.onpointermove=null};$(`[data-app="${id}"]`).classList.add('running');focusWin(id);renderApp(id)}
function body(id){return $('.window-body',wins[id])}function renderApp(id){({files:renderFiles,trash:()=>renderFiles(true),notes:renderNotes,settings:renderSettings,terminal:renderTerminal,calculator:renderCalc,calendar:renderCalendar,browser:renderBrowser,music:renderMusic}[id])()}
function persistFiles(){save('files',files);stats();if(wins.files)renderFiles();if(wins.trash)renderFiles(true)}
function renderFiles(trash=false){const root=body(trash?'trash':'files');root.innerHTML=`<div class="split"><aside class="sidebar"><small>ИЗБРАННОЕ</small>${['Все файлы','Документы','Изображения','Загрузки'].map(f=>`<button class="${f===folder&&!trash?'selected':''}" data-folder="${f}">${f==='Изображения'?'▧':'▱'} &nbsp;${f}</button>`).join('')}<small style="margin-top:25px">ХРАНИЛИЩЕ</small><button data-trash>♲ &nbsp; Корзина</button></aside><div class="content"><div class="toolbar">${trash?'<button id="empty-trash">Очистить корзину</button>':'<button id="new-file">+ Файл</button><button id="upload">↑ Импорт</button>'}<input id="file-search" placeholder="Найти файл" aria-label="Поиск файлов"></div><div class="file-grid"></div><div class="status">${trash?'Нажмите на файл для восстановления':'Двойной клик — открыть · правая кнопка — действия'}</div></div></div>`;const grid=$('.file-grid',root);function draw(q=''){let list=files.filter(f=>!!f.deleted===trash&&(trash||folder==='Все файлы'||f.folder===folder)&&f.name.toLowerCase().includes(q.toLowerCase()));grid.innerHTML=list.length?list.map(f=>`<button class="file-card" data-id="${f.id}"><span class="glyph">${f.type?.startsWith('image/')?'▧':'▤'}</span><span>${esc(f.name)}</span></button>`).join(''):'<div class="empty">Пока пусто.<br>Здесь появятся ваши файлы.</div>';$$('.file-card',grid).forEach(b=>{const f=files.find(f=>f.id===b.dataset.id);b.ondblclick=()=>trash?restore(f):openFile(f);if(trash)b.onclick=()=>restore(f);b.oncontextmenu=e=>{e.preventDefault();fileMenu(f,trash)}})}draw();$('#file-search',root).oninput=e=>draw(e.target.value);$$('[data-folder]',root).forEach(b=>b.onclick=()=>{folder=b.dataset.folder;if(trash)openApp('files');else renderFiles()});$('[data-trash]',root).onclick=()=>openApp('trash');if(trash){$('#empty-trash',root).onclick=()=>confirmDialog('Удалить файлы навсегда?','Это действие нельзя отменить.',()=>{files=files.filter(f=>!f.deleted);persistFiles()})}else{$('#new-file',root).onclick=()=>inputDialog('Новый текстовый файл','Идея.txt',name=>{files.push({id:crypto.randomUUID(),name:name.endsWith('.txt')?name:name+'.txt',text:'',type:'text/plain',folder:folder==='Все файлы'?'Документы':folder});persistFiles()});$('#upload',root).onclick=()=>$('#import-file').click()}}
function restore(f){delete f.deleted;persistFiles();toast('Файл восстановлен')}
function fileMenu(f,trash){const box=showPanel(`<h3>${esc(f.name)}</h3>${trash?'<button data-action="restore">Восстановить</button>':'<button data-action="open">Открыть</button><button data-action="rename">Переименовать</button><button data-action="download">Скачать</button><button data-action="delete">В корзину</button>'}`);$$('button',box).forEach(b=>b.onclick=()=>{closeOverlay();if(b.dataset.action==='restore')restore(f);if(b.dataset.action==='open')openFile(f);if(b.dataset.action==='rename')inputDialog('Имя файла',f.name,name=>{f.name=name;persistFiles()});if(b.dataset.action==='download')downloadFile(f);if(b.dataset.action==='delete'){f.deleted=true;persistFiles();toast('Файл перемещён в корзину')}})}
$('#import-file').onchange=async e=>{for(const file of e.target.files){if(file.size>2*1024*1024){toast('Максимальный размер файла — 2 МБ');continue}const reader=new FileReader();reader.onload=()=>{const item={id:crypto.randomUUID(),name:file.name,type:file.type,data:reader.result,folder:file.type.startsWith('image/')?'Изображения':'Загрузки'};const next=[...files,item];if(save('files',next)){files=next;persistFiles()}};reader.readAsDataURL(file)}e.target.value=''};
function download(name,data,type='text/plain'){const url=URL.createObjectURL(new Blob([data],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function downloadFile(f){if(f.data){const a=document.createElement('a');a.href=f.data;a.download=f.name;a.click()}else download(f.name,f.text||'')}
function openFile(f){if(f.type?.startsWith('image/')){const box=showPanel(`<h3>${esc(f.name)}</h3><img src="${esc(f.data)}" style="width:100%;max-height:55vh;object-fit:contain" alt="${esc(f.name)}">`);box.style.width='min(700px,90vw)';return}if(f.type==='text/plain'||/\.(txt|md|json|css|js|csv)$/i.test(f.name)){let text=f.text;if(text===undefined&&f.data){try{text=new TextDecoder().decode(Uint8Array.from(atob(f.data.split(',')[1]),c=>c.charCodeAt(0)))}catch{text=''}}const box=showPanel(`<h3>${esc(f.name)}</h3><textarea style="width:100%;height:40vh;border:1px solid #ccc;border-radius:8px;padding:15px;resize:vertical" aria-label="Текст файла">${esc(text||'')}</textarea><button id="save-file">Сохранить файл</button>`);box.style.width='min(650px,90vw)';$('#save-file',box).onclick=()=>{f.text=$('textarea',box).value;delete f.data;persistFiles();closeOverlay();toast('Файл сохранён')};return}showPanel(`<h3>${esc(f.name)}</h3><p>Для этого формата доступно скачивание.</p><button id="download-file">Скачать файл</button>`);$('#download-file').onclick=()=>downloadFile(f)}
function renderNotes(){const root=body('notes');const n=notes.find(n=>n.id===selectedNote)||notes[0];selectedNote=n?.id;root.innerHTML=`<div class="split"><aside class="sidebar"><button id="add-note">+ Новая заметка</button>${notes.map(x=>`<button class="note-item ${x.id===selectedNote?'selected':''}" data-note="${x.id}">${esc(x.title||'Без названия')}</button>`).join('')}</aside><div class="content">${n?`<div class="note-editor"><div class="toolbar"><span style="color:#8b9280;font-size:11px">Сохранено на устройстве</span><button id="export-note" style="margin-left:auto">↓ Экспорт</button><button id="delete-note">Удалить</button></div><input id="note-title" aria-label="Название заметки" value="${esc(n.title)}"><textarea id="note-text" aria-label="Текст заметки" placeholder="Начните писать…">${esc(n.text)}</textarea></div>`:'<div class="empty">Создайте первую заметку</div>'}</div></div>`;$('#add-note',root).onclick=()=>{const n={id:crypto.randomUUID(),title:'Новая заметка',text:''};notes.unshift(n);selectedNote=n.id;save('notes',notes);renderNotes()};$$('[data-note]',root).forEach(b=>b.onclick=()=>{selectedNote=b.dataset.note;renderNotes()});if(n){$('#note-title',root).oninput=e=>{n.title=e.target.value;save('notes',notes);$(`[data-note="${n.id}"]`,root).textContent=n.title||'Без названия'};$('#note-text',root).oninput=e=>{n.text=e.target.value;save('notes',notes)};$('#delete-note',root).onclick=()=>confirmDialog('Удалить заметку?','Сначала можно экспортировать её в текстовый файл.',()=>{notes=notes.filter(x=>x.id!==n.id);save('notes',notes);renderNotes()});$('#export-note',root).onclick=()=>download(n.title+'.txt',n.text)}}
function renderSettings(){const root=body('settings');root.innerHTML=`<div class="settings"><h2>Всё по-вашему.</h2><p style="color:#8b9281">Небольшие детали. Ваше пространство.</p><div class="setting-row"><span>Ваше имя<small>Приветствие на рабочем столе</small></span><input type="text" id="user-name" maxlength="24" value="${esc(settings.name)}" aria-label="Ваше имя"></div><div class="setting-row"><span>Тёмное оформление</span><input id="dark-mode" type="checkbox" class="switch" ${settings.dark?'checked':''}></div><div class="setting-row"><span>Концентрация<small>Приглушить второстепенные виджеты</small></span><input id="focus-mode" type="checkbox" class="switch" ${settings.focus?'checked':''}></div><div class="setting-row"><span>Обои</span><div class="wall-options">${['#c8cac3','#adbe97','#d1b6a9'].map((c,i)=>`<button class="wall-option" data-wall="${i}" style="background:${c};outline:${settings.wall===i?'2px solid #78866a':'none'}" aria-label="Обои ${i+1}"></button>`).join('')}</div></div><div class="setting-row"><span>Резервная копия<small>Файлы, заметки, календарь и настройки</small></span><button class="soft-button" id="backup">Экспорт</button></div><div class="setting-row"><span>Восстановить копию<small>Заменит данные после подтверждения</small></span><button class="soft-button" id="restore-backup">Импорт</button><input type="file" accept=".json" id="backup-input" hidden></div><p style="font-size:11px;color:#858d7b;line-height:1.7">Forma 1.0 · Web Desktop<br>Данные хранятся в этом браузере. Очистка данных сайта удалит их. Веб-среда не имеет доступа к системным приложениям или файлам без вашего выбора.</p></div>`;$('#user-name',root).oninput=e=>{settings.name=e.target.value;applySettings()};$('#dark-mode',root).onchange=e=>{settings.dark=e.target.checked;applySettings()};$('#focus-mode',root).onchange=e=>{settings.focus=e.target.checked;applySettings()};$$('[data-wall]',root).forEach(b=>b.onclick=()=>{settings.wall=+b.dataset.wall;applySettings();renderSettings()});$('#backup',root).onclick=()=>download('forma-backup.json',JSON.stringify({version:1,files,notes,events,settings,quick:$('#quick-note').value},null,2),'application/json');$('#restore-backup',root).onclick=()=>$('#backup-input',root).click();$('#backup-input',root).onchange=async e=>{try{const data=JSON.parse(await e.target.files[0].text());if(data.version!==1||!Array.isArray(data.files)||!Array.isArray(data.notes)||!data.files.every(f=>typeof f.id==='string'&&typeof f.name==='string')||!data.notes.every(n=>typeof n.id==='string'&&typeof n.text==='string'&&typeof n.title==='string'))throw Error();confirmDialog('Восстановить резервную копию?','Текущие файлы и заметки будут заменены.',()=>{const old={files,notes,events,settings,quick:read('quick','')};try{for(const key of ['files','notes','events','settings','quick']){if(!save(key,data[key]??old[key]))throw Error()}location.reload()}catch{for(const [key,v] of Object.entries(old))save(key,v);toast('Недостаточно места для восстановления')}})}catch{toast('Не удалось прочитать резервную копию Forma')}}}
function renderTerminal(){const root=body('terminal');root.innerHTML='<div class="terminal"><pre>Forma Shell 1.0\nВиртуальная файловая система · введите help\n\n</pre><form><span>guest@forma ~ %</span><input aria-label="Команда терминала" autocomplete="off" spellcheck="false"></form></div>';const out=$('pre',root),input=$('input',root);$('form',root).onsubmit=e=>{e.preventDefault();let cmd=input.value.trim();input.value='';out.textContent+='guest@forma ~ % '+cmd+'\n';const [c,...args]=cmd.split(' '),arg=args.join(' ');let result='';switch(c){case 'help':result='help                список команд\nls                  файлы\ncat <имя>           прочитать текст\ntouch <имя>         создать файл\nrm <имя>            переместить в корзину\necho <текст>        вывести текст\ndate                дата и время\npwd                 текущая папка\nwhoami              пользователь\nopen <приложение>   notes, files, calendar…\nclear               очистить экран';break;case 'ls':result=files.filter(f=>!f.deleted).map(f=>f.name).join('\n')||'(пусто)';break;case 'pwd':result='/Users/guest';break;case 'whoami':result=settings.name||'guest';break;case 'date':result=new Date().toLocaleString('ru-RU');break;case 'echo':result=arg;break;case 'cat':{let f=files.find(f=>f.name===arg&&!f.deleted);result=f?f.text??'Импортированный файл: откройте его в Файлах.':'Файл не найден';break}case 'touch':if(!arg)result='Укажите имя файла';else if(files.some(f=>f.name===arg&&!f.deleted))result='Файл уже существует';else{files.push({id:crypto.randomUUID(),name:arg,text:'',type:'text/plain',folder:'Документы'});persistFiles();result='Создан: '+arg}break;case 'rm':{let f=files.find(f=>f.name===arg&&!f.deleted);if(f){f.deleted=true;persistFiles();result='Перемещён в корзину'}else result='Файл не найден';break}case 'open':if(apps[arg])openApp(arg);else result='Приложения: '+Object.keys(apps).join(', ');break;case 'clear':out.textContent='';break;case '':break;default:result='Команда не найдена. Введите help.'}if(result)out.textContent+=result+'\n';$('.terminal',root).scrollTop=1e7};input.focus()}
function renderCalc(){const root=body('calculator');root.innerHTML='<div class="calc"><div class="calc-output">0</div><div class="calc-grid">'+['AC','±','%','÷','7','8','9','×','4','5','6','−','1','2','3','+','0','.','⌫','='].map(k=>`<button class="${'÷×−+=' .includes(k)?'op':''}">${k}</button>`).join('')+'</div></div>';let current='0',left=null,op=null,fresh=false;const output=$('.calc-output',root);function operate(){const a=+left,b=+current;return op==='+'?a+b:op==='−'?a-b:op==='×'?a*b:b===0?NaN:a/b}$$('.calc-grid button',root).forEach(b=>b.onclick=()=>{const k=b.textContent;if(k==='AC'){current='0';left=op=null;fresh=false}else if(k==='±')current=String(-Number(current));else if(k==='%')current=String(Number(current)/100);else if(k==='⌫')current=current.slice(0,-1)||'0';else if('÷×−+'.includes(k)){if(op&&!fresh)current=String(operate());left=current;op=k;fresh=true}else if(k==='='){if(op){current=String(operate());op=null;fresh=true}}else{if(fresh){current='0';fresh=false}if(k==='.'&&current.includes('.'))return;current=current==='0'&&k!=='.'?k:current+k}if(current.length>16)current=String(Number(current).toPrecision(10));output.textContent=Number.isFinite(+current)?current:'Ошибка';if(!Number.isFinite(+current)){current='0';op=null;fresh=true}})}
let calDate=new Date(),selectedDate=new Date().toLocaleDateString('sv-SE');
function renderCalendar(){const root=body('calendar'),year=calDate.getFullYear(),month=calDate.getMonth(),start=(new Date(year,month,1).getDay()+6)%7,total=new Date(year,month+1,0).getDate();root.innerHTML=`<div class="calendar"><div class="calendar-head"><button id="prev-month" aria-label="Предыдущий месяц">‹</button><span>${calDate.toLocaleDateString('ru-RU',{month:'long',year:'numeric'})}</span><button id="next-month" aria-label="Следующий месяц">›</button></div><div class="calendar-grid">${['ПН','ВТ','СР','ЧТ','ПТ','СБ','ВС'].map(x=>'<small>'+x+'</small>').join('')}${'<span></span>'.repeat(start)}${Array.from({length:total},(_,i)=>{const date=year+'-'+String(month+1).padStart(2,'0')+'-'+String(i+1).padStart(2,'0');return `<button data-date="${date}" class="${date===new Date().toLocaleDateString('sv-SE')?'today':''} ${date===selectedDate?'selected':''}">${i+1}${events[date]?.length?' •':''}</button>`}).join('')}</div><form class="event-input"><input placeholder="Событие на ${selectedDate}" aria-label="Новое событие" required maxlength="120"><button class="soft-button">+ Добавить</button></form><div>${(events[selectedDate]||[]).map((s,i)=>`<div class="event-row">${esc(s)}<button data-delete-event="${i}" aria-label="Удалить событие">×</button></div>`).join('')}</div><p style="font-size:10px;color:#8b9281">События сохраняются локально. Системные уведомления не отправляются.</p></div>`;$('#prev-month',root).onclick=()=>{calDate=new Date(year,month-1,1);renderCalendar()};$('#next-month',root).onclick=()=>{calDate=new Date(year,month+1,1);renderCalendar()};$$('[data-date]',root).forEach(b=>b.onclick=()=>{selectedDate=b.dataset.date;renderCalendar()});$('form',root).onsubmit=e=>{e.preventDefault();const val=$('input',root).value.trim();if(!val)return;(events[selectedDate]??=[]).push(val);save('events',events);renderCalendar()};$$('[data-delete-event]',root).forEach(b=>b.onclick=()=>{events[selectedDate].splice(+b.dataset.deleteEvent,1);save('events',events);renderCalendar()})}
function renderBrowser(){const root=body('browser');root.innerHTML='<div class="browser-home"><span class="eyebrow">ОКНО В ИНТЕРНЕТ</span><h2>Куда отправимся?</h2><form class="event-input"><input aria-label="Адрес или поисковый запрос" placeholder="Введите адрес или поисковый запрос" required><button class="soft-button">Перейти ↗</button></form><div class="bookmarks"><a href="https://www.wikipedia.org" target="_blank" rel="noopener">Wikipedia ↗</a><a href="https://github.com" target="_blank" rel="noopener">GitHub ↗</a><a href="https://ya.ru" target="_blank" rel="noopener">Яндекс ↗</a></div><p style="color:#8b9281;font-size:11px;line-height:1.8">Сайты открываются в новой вкладке вашего браузера.<br>Это позволяет использовать авторизацию и избежать ограничений встраивания.</p></div>';$('form',root).onsubmit=e=>{e.preventDefault();const q=$('input',root).value.trim();let url;if(/^https?:\/\//i.test(q))url=q;else if(/^[\w.-]+\.[a-z]{2,}(\/.*)?$/i.test(q))url='https://'+q;else url='https://ya.ru/search/?text='+encodeURIComponent(q);window.open(url,'_blank','noopener,noreferrer')}}
function renderMusic(){const root=body('music');root.innerHTML='<div class="music"><div class="album">♫</div><h2 id="track-name">Ваш личный саундтрек</h2><p style="color:#8b9281">Выберите аудиофайл с устройства</p><audio controls></audio><br><button class="soft-button" id="pick-audio">+ Открыть музыку</button><input type="file" accept="audio/*" hidden><p style="font-size:10px;color:#8b9281;margin-top:25px">Аудио воспроизводится локально и не загружается на сервер.</p></div>';$('#pick-audio',root).onclick=()=>$('input',root).click();$('input',root).onchange=e=>{const f=e.target.files[0];if(!f)return;const audio=$('audio',root);if(audio.src)URL.revokeObjectURL(audio.src);audio.src=URL.createObjectURL(f);$('#track-name',root).textContent=f.name;audio.play().catch(()=>toast('Нажмите ▶ для воспроизведения'))}}
function closeOverlay(){$('#overlay').hidden=true;$('#overlay').innerHTML=''}
function showPanel(html){const o=$('#overlay');o.hidden=false;o.innerHTML='<div class="control-panel">'+html+'</div>';o.onclick=e=>{if(e.target===o)closeOverlay()};return $('.control-panel',o)}
function inputDialog(title,value,fn){const box=showPanel(`<h3>${esc(title)}</h3><form><input value="${esc(value)}" required maxlength="100" style="padding:10px;width:100%;border:1px solid #ccc;border-radius:7px" aria-label="${esc(title)}"><button>Сохранить</button><button type="button" id="cancel">Отмена</button></form>`);$('input',box).focus();$('input',box).select();$('form',box).onsubmit=e=>{e.preventDefault();const value=$('input',box).value.trim();if(!value)return;closeOverlay();fn(value)};$('#cancel',box).onclick=closeOverlay}
function confirmDialog(title,text,fn){const box=showPanel(`<h3>${esc(title)}</h3><p>${esc(text)}</p><button id="confirm">Подтвердить</button><button id="cancel">Отмена</button>`);$('#confirm',box).onclick=()=>{closeOverlay();fn()};$('#cancel',box).onclick=closeOverlay}
function spotlight(){const o=$('#overlay');o.hidden=false;o.innerHTML='<div class="spotlight"><input placeholder="Найти приложение…" aria-label="Поиск приложений"><div id="results"></div><small style="display:block;padding:10px;color:#8b9281">Enter — открыть · Esc — закрыть</small></div>';o.onclick=e=>{if(e.target===o)closeOverlay()};const input=$('input',o);function results(){const q=input.value.toLowerCase();$('#results',o).innerHTML=Object.entries(apps).filter(([id,a])=>a.name.toLowerCase().includes(q)||id.includes(q)).map(([id,a])=>`<button data-result="${id}"><span class="app-icon">${a.icon}</span>${a.name}<span style="margin-left:auto;color:#8b9281">↗</span></button>`).join('')||'<p class="empty">Ничего не найдено</p>';$$('[data-result]',o).forEach(b=>b.onclick=()=>openApp(b.dataset.result))}input.oninput=results;input.onkeydown=e=>{if(e.key==='Enter')$('[data-result]',o)?.click()};results();input.focus()}
$('#search-top').onclick=spotlight;$('#view-menu').onclick=()=>{Object.values(wins).forEach(w=>w.style.display='none');$('#active-app').textContent='Forma'};$('#file-menu').onclick=()=>{showPanel('<h3>Файл</h3><button id="menu-files">Открыть файлы</button><button id="menu-notes">Новая заметка</button>');$('#menu-files').onclick=()=>openApp('files');$('#menu-notes').onclick=()=>{openApp('notes');$('#add-note',body('notes')).click()}};
function about(){const box=showPanel('<div class="about"><div class="logo">✺</div><h2>Forma OS</h2><p>Ваше пространство. В вашем ритме.</p><p>Версия 1.0 · Веб-среда</p><p><kbd>⌘ / Ctrl</kbd> + <kbd>K</kbd> — поиск<br>Двойной клик по заголовку — развернуть окно.<br>Окна можно перемещать и менять в размере.</p><p>Заметки, файлы и события хранятся в браузере.<br>Резервная копия доступна в Настройках.</p></div>');box.style.width='min(470px,90vw)'}
$('#brand').onclick=about;$('#help').onclick=about;$('#focus-top').onclick=()=>{settings.focus=!settings.focus;applySettings();toast(settings.focus?'Режим концентрации включён':'Режим концентрации выключен')};$('#control-top').onclick=()=>{const box=showPanel(`<h3>Пункт управления</h3><button id="toggle-dark">${settings.dark?'☀ Светлое':'☾ Тёмное'} оформление</button><button id="toggle-focus">◉ Концентрация: ${settings.focus?'включена':'выключена'}</button><button id="fullscreen">⛶ Полный экран</button><label>Яркость рабочего стола<input id="brightness" type="range" min="50" max="100" value="${Math.round((parseFloat($('#desktop').style.opacity)||1)*100)}"></label><button id="all-settings">Все настройки →</button>`);$('#toggle-dark',box).onclick=()=>{settings.dark=!settings.dark;applySettings();closeOverlay()};$('#toggle-focus',box).onclick=()=>{settings.focus=!settings.focus;applySettings();closeOverlay()};$('#fullscreen',box).onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen();closeOverlay()}catch{toast('Полный экран недоступен в этом браузере')}};$('#brightness',box).oninput=e=>$('#desktop').style.opacity=e.target.value/100;$('#all-settings',box).onclick=()=>openApp('settings')};
document.onkeydown=e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();spotlight()}if(e.key==='Escape')closeOverlay()};document.addEventListener('visibilitychange',()=>{if(!document.hidden)updateTimer()});
